    // Sets the rating only if the ticket has none; says whether it did. On Postgres: UPDATE ... WHERE csat_score IS NULL.
    rateTicketIfUnrated(id, rating) {
      const t = tickets.get(id);
      if (!t) throw new Error(`no ticket ${id}`);
      if (t.csat_score != null) return false;
      Object.assign(t, rating);
      return true;
    },
    listRatedSince(iso) {
      return [...tickets.values()].filter((t) => t.csat_rated_at != null && t.csat_rated_at >= iso).map((t) => ({ ...t }));
    },
    upsertAgentSummary(row) {
      summaries.set(`${row.agent_id}|${row.summary_date}`, { ...row });
    },
    listAgentSummaries(filter = {}) {
      return [...summaries.values()].filter((s) => Object.entries(filter).every(([k, v]) => s[k] === v)).map((s) => ({ ...s }));
    },
```

(ISO strings from `toISOString()` all have the same shape, so string comparison orders them by time.)

