// The customer rates a resolved ticket once, 1 to 5. A ticket of another organisation looks like a missing one. A low
// score tells the owner, when there is one.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating is a whole number from 1 to 5');
  const stored = store.rateTicketIfUnrated(id, { csat_score: score, csat_rated_at: now.toISOString() });
  if (!stored) throw new Error('this ticket is already rated');
  if (score <= LOW_SCORE && t.owner_id) notifyAgent(store, t.owner_id, { type: 'low_rating', ticketId: id, score });
  return getMyTicket(store, customer, id);
}
```

