'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/store');
const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
const { drain } = require('../src/notify');
const portal = require('../src/portal');
const { weeklyCsatSummary } = require('../src/jobs/weekly-csat-summary');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };

// A ticket owned by `owner` (or nobody), rated `score` on day `ratedOn`.
function rated(store, { owner, score, ratedOn }) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
  if (owner) assignTicket(store, t.id, owner);
  resolveTicket(store, t.id, 41, { now: at(1) });
  portal.rateTicket(store, acme, t.id, score, { now: at(ratedOn) });
  return t;
}

test('ratings 5, 4 and 1 in the past seven days give three ratings and an average of 3.33; an eight day old rating is not counted', () => {
  const store = createStore();
  drain();
  rated(store, { owner: 41, score: 5, ratedOn: 19 });
  rated(store, { owner: 41, score: 4, ratedOn: 16 });
  rated(store, { owner: 41, score: 1, ratedOn: 14 });
  rated(store, { owner: 41, score: 1, ratedOn: 12 }); // eight days before day 20
  weeklyCsatSummary(store, { now: at(20) });
  const [row] = store.listAgentSummaries({ agent_id: 41 });
  assert.equal(row.rating_count, 3);
  assert.equal(row.average_score, 3.33);
  assert.equal(row.summary_date, '2026-01-21');
  assert.equal(row.period_end, at(20).toISOString());
  assert.equal(row.period_start, at(13).toISOString());
});

test('a rating exactly seven days old is counted', () => {
  const store = createStore();
  rated(store, { owner: 41, score: 4, ratedOn: 13 });
  weeklyCsatSummary(store, { now: at(20) });
  assert.equal(store.listAgentSummaries({ agent_id: 41 })[0].rating_count, 1);
});

test('each agent gets their own row; agents without ratings and unowned tickets get none', () => {
  const store = createStore();
  rated(store, { owner: 41, score: 5, ratedOn: 18 });
  rated(store, { owner: 42, score: 2, ratedOn: 18 });
  rated(store, { owner: null, score: 3, ratedOn: 18 });
  createTicket(store, { orgId: 1, customerId: 7, subject: 'Unrated', body: 'x', now: at(0) });
  const written = weeklyCsatSummary(store, { now: at(20) });
  assert.deepEqual(written.map((r) => [r.agent_id, r.rating_count, r.average_score]), [[41, 1, 5], [42, 1, 2]]);
  assert.deepEqual(store.listAgentSummaries().map((r) => r.agent_id), [41, 42]);
});

test('running the job twice on one day leaves one row per agent, and a later day adds another', () => {
  const store = createStore();
  rated(store, { owner: 41, score: 5, ratedOn: 18 });
  weeklyCsatSummary(store, { now: at(20) });
  rated(store, { owner: 41, score: 3, ratedOn: 19 });
