```js
'use strict';
// Nightly. For each agent, counts the ratings that arrived on their tickets in the past seven days and averages the
// scores. The result is kept as that day's summary, so a second run on the same day replaces the first. An agent with
// no ratings in the window gets no row, and a ticket with no owner counts for nobody.
const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyCsatSummary(store, { now = new Date() } = {}) {
  const since = new Date(now.getTime() - WINDOW_DAYS * DAY);
  const scoresByAgent = new Map();
  for (const t of store.listRatedSince(since.toISOString())) {
    if (!t.owner_id) continue;
    if (!scoresByAgent.has(t.owner_id)) scoresByAgent.set(t.owner_id, []);
    scoresByAgent.get(t.owner_id).push(t.csat_score);
  }
  const written = [];
  for (const [agentId, scores] of scoresByAgent) {
    const sum = scores.reduce((a, b) => a + b, 0);
    const row = {
      agent_id: agentId,
      summary_date: now.toISOString().slice(0, 10),
      period_start: since.toISOString(),
      period_end: now.toISOString(),
      rating_count: scores.length,
      average_score: Math.round((sum / scores.length) * 100) / 100,
    };
    store.upsertAgentSummary(row);
    written.push(row);
  }
  return written;
}

module.exports = { weeklyCsatSummary, WINDOW_DAYS };
```

